const fs=require('fs');const c=require('F:/Pokemon Arcade/src/data/catalog.json');
const list={Arcanine:59,Ninetales:38,Rapidash:78,Jolteon:135,Raichu:26,Electabuzz:125,Vaporeon:134,Gyarados:130,Lapras:131,Cloyster:91,Scyther:123,Pinsir:127,Golem:76,Rhydon:112,Nidoking:34,Nidoqueen:31,Dragonite:149,Aerodactyl:142,Mewtwo:150,Articuno:144};
(async()=>{let pointer=0;await Promise.all(Array.from({length:3},async()=>{const entries=Object.entries(list);while(pointer<entries.length){const [name,id]=entries[pointer++],file=`assets/models/${name}.glb`;if(!fs.existsSync(file)){const r=await fetch(`https://raw.githubusercontent.com/06wj/pokemon/master/public/models/${String(id).padStart(3,'0')}/model.glb`);if(!r.ok)throw Error(name+': '+r.status);fs.writeFileSync(file,Buffer.from(await r.arrayBuffer()));}const b=fs.readFileSync(file),j=JSON.parse(b.subarray(20,20+b.readUInt32LE(12)));console.log(name,b.length,j.animations?.map(a=>a.name).join(','));}}));const stats={source:'Existing local PokéAPI catalog',species:{}};for(const [name,id]of Object.entries(list))stats.species[name]=c.forms.find(f=>f.id===id);fs.writeFileSync('assets/boss-source.json',JSON.stringify(stats,null,2));})().catch(e=>{console.error(e);process.exit(1)});
